    /**
     * Check room availability for a given date/time range, same conflict
     * logic as the public booking flow (Front\FrontController::submitRuangan):
     * a booking blocks a room unless it's Rejected or already Terlaksana,
     * and combination rooms share conflicts with their member rooms via
     * Ruang::footprintMap().
     *
     * @return \Illuminate\Http\JsonResponse
     */
    public function checkAvailability(Request $request)
    {
        if (!$request->filled('tanggal') || !$request->filled('waktu_awal') || !$request->filled('waktu_akhir')) {
            return response()->json([
                'html' => '<div class="avail-empty">Tanggal, jam mulai, dan jam selesai wajib diisi.</div>',
            ]);
        }

        $conflict = $this->resolveConflict(
            $request->get('tanggal'),
            $request->get('waktu_awal'),
            $request->get('waktu_akhir')
        );

        $ruangs = $this->ruang->get();
        $ruangs->each(function ($r) use ($conflict) {
            $footprint = $conflict['footprintMap'][(int) $r->id] ?? [(int) $r->id];
            $r->is_conflicted = count(array_intersect($footprint, $conflict['conflictingAtomicIds'])) > 0;

            $names = [];
            foreach ($footprint as $atomicId) {
                foreach ($conflict['bookerNamesByAtomicId'][$atomicId] ?? [] as $name) {
                    $names[] = $name;
                }
            }
            $r->conflict_booker_names = array_values(array_unique($names));
        });

        $data['ruangs'] = $ruangs;

        return response()->json([
            'html' => view('admin::pemesanan_ruangan.partials.availability-list', $data)->render(),
        ]);
    }

    /**
     * List only the rooms that are NOT conflicted for a given date/time, for
     * populating the create/edit form's room select. When editing an
     * existing booking, pass exclude_id so the booking doesn't conflict
     * with itself.
     *
     * @return \Illuminate\Http\JsonResponse
     */
    public function availableRooms(Request $request)
    {
        if (!$request->filled('tanggal') || !$request->filled('waktu_awal') || !$request->filled('waktu_akhir')) {
            return response()->json(['rooms' => []]);
        }

        $conflict = $this->resolveConflict(
            $request->get('tanggal'),
            $request->get('waktu_awal'),
            $request->get('waktu_akhir'),
            $request->get('exclude_id')
        );

        $rooms = $this->ruang->get()
            ->filter(function ($r) use ($conflict) {
                $footprint = $conflict['footprintMap'][(int) $r->id] ?? [(int) $r->id];
                return count(array_intersect($footprint, $conflict['conflictingAtomicIds'])) === 0;
            })
            ->values()
            ->map(function ($r) {
                return ['id' => $r->id, 'label' => $r->id . ' - ' . $r->nama_ruang];
            });

        return response()->json(['rooms' => $rooms]);
    }

    /**
     * Compute which atomic room ids are booked-out for a date/time range,
     * and who's occupying them. Shared by checkAvailability(), availableRooms(),
     * and assertRoomAvailable() so all three agree on exactly one definition
     * of "conflict" (same rule as the public booking flow: a booking blocks
     * unless Rejected or already Terlaksana).
     *
     * @param  string      $tanggal   Y-m-d
     * @param  string      $waktuAwalInput  H:i
     * @param  string      $waktuAkhirInput H:i
     * @param  int|null    $excludeId Booking id to ignore (the booking being edited)
     * @return array{footprintMap: array, conflictingAtomicIds: array, bookerNamesByAtomicId: array}
     */
    protected function resolveConflict($tanggal, $waktuAwalInput, $waktuAkhirInput, $excludeId = null)
    {
        $waktu_awal = intval(str_replace(':', '', $waktuAwalInput));
        $waktu_akhir = intval(str_replace(':', '', $waktuAkhirInput));

        $conflictingBookings = $this->pemesananRuangan
            ->where('tanggal_selesai', '>=', $tanggal)
            ->where('tanggal', '<=', $tanggal)
            ->where('status_pj', '!=', 'Rejected')
            ->where('status_pelaksana', 'Belum Terlaksana')
            ->when($excludeId, function ($query) use ($excludeId) {
                $query->where('id', '!=', $excludeId);
            })
            ->get()
            ->filter(function ($q) use ($waktu_awal, $waktu_akhir) {
                $time_awal = intval(date('Hi', $q->waktu_awal));
                $time_akhir = intval(date('Hi', $q->waktu_akhir));
                return $time_awal < $waktu_akhir && $waktu_awal < $time_akhir;
            });

        $footprintMap = Ruang::footprintMap();
        $conflictingAtomicIds = [];
        $bookerNamesByAtomicId = [];
        foreach ($conflictingBookings as $booking) {
            $bookingFootprint = $footprintMap[(int) $booking->id_ruang] ?? [(int) $booking->id_ruang];
            $bookerName = $booking->pemohon;
            foreach ($bookingFootprint as $atomicId) {
                $conflictingAtomicIds[] = $atomicId;
                if ($bookerName) {
                    $bookerNamesByAtomicId[$atomicId][] = $bookerName;
                }
            }
        }

        return [
            'footprintMap' => $footprintMap,
            'conflictingAtomicIds' => array_unique($conflictingAtomicIds),
            'bookerNamesByAtomicId' => $bookerNamesByAtomicId,
        ];
    }

    /**
     * Server-side guard against a room double-booking, run right before
     * save on both create and edit. Client-side filtering (availableRooms)
     * keeps the UI honest, but this is what actually prevents a conflicting
     * booking from being persisted (e.g. two admins submitting at once, or
     * a stale form). Excludes the booking's own row on edit.
     *
     * @throws \Illuminate\Validation\ValidationException
     */
    protected function assertRoomAvailable(Request $request, $excludeId = null)
    {
        $tanggal = $request->get('tanggal');
        $waktuAwal = $request->get('waktu_awal');
        $waktuAkhir = $request->get('waktu_akhir');
        $idRuang = $request->get('id_ruang');

        if (!$tanggal || !$waktuAwal || !$waktuAkhir || !$idRuang) {
            return;
        }

        $conflict = $this->resolveConflict($tanggal, $waktuAwal, $waktuAkhir, $excludeId);
        $footprint = $conflict['footprintMap'][(int) $idRuang] ?? [(int) $idRuang];
        $isConflicted = count(array_intersect($footprint, $conflict['conflictingAtomicIds'])) > 0;

        if (!$isConflicted) {
            return;
        }

        $names = [];
        foreach ($footprint as $atomicId) {
            foreach ($conflict['bookerNamesByAtomicId'][$atomicId] ?? [] as $name) {
                $names[] = $name;
            }
        }
        $names = array_values(array_unique($names));

        $message = 'Ruangan yang dipilih sudah dipakai pada tanggal dan jam tersebut'
            . (!empty($names) ? ' oleh: ' . implode(', ', $names) : '') . '.';

        throw ValidationException::withMessages(['id_ruang' => $message]);
    }

    /**
     * Show detail pemesananRuangan
     *
     * @param  Illuminate\Http\Request $request
     * @param  string $id
     * @return Illuminate\Http\Response
     */
    public function pageDetail(Request $request, $id)
    {
        $pemesananRuangan = $this->findOrFail($id);

        $notif = Notification::where('pemesanan_ruangan_id',$pemesananRuangan->id)->first();
        $notif->status = true;
        $notif->save();
        
        $data['title'] = 'Detail Pemesanan Ruangan';
        $data['pemesananRuangan'] = $pemesananRuangan;

        return view('admin::pemesanan_ruangan.page-detail', $data);
    }

