           /**
     * Get ID Ruang
     *
     * @return array
     */
    protected function getRuangan()
    {
        return $this->ruang
            ->select(['id as value', \DB::raw('concat(id, " - ", nama_ruang) as label')])
            ->get()
            ->toArray();
    }

    protected function getPemohon()
    {
        return $this->karyawan
            ->select(['nama as value', 'nama as label'])
            ->get()
            ->toArray();
    }

    /**
     * Get Design Ruangan options (same layout list used on the public
     * booking form, App\Models\LayoutRuang: Classroom, U-Shape, etc.)
     *
     * @return array
     */
    protected function getLayoutRuang()
    {
        return LayoutRuang::select(['nama_layout_ruang as value', 'nama_layout_ruang as label'])
            ->get()
            ->toArray();
    }
